# DK SMM.  Sønderborg - Mommark Færge
#
let sm = path("d3.dk.smm");

with detail = 4, railway = :first :pax :removed {
    # point.dk.Sønderborg  dk.SBT

    with link = "line.dk.SMM" {
        track(:station, sm[:son.ym, :son.a]);
        track(sm[:son.a - 0.1dl, :sob - 0.49sw]);
    }

    with link = "point.dk.Sønderborg-By", railway = :station {
        track(sm[:sob - 0.5sw, :sob + 0.5sw]);
        marker(:left :de.bf, sm[:sob] << 0.5mt);
        station(:bottom, sm[:sob] >> 0.5mt + (1dt, 1dt),
            span(:former, "Sonderburg"),
            "Sønderborg By",
            hbox(:center:top,
                vbox(:right:top, span(:former, "SSB: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "0,", "0"),
                    hbox(:sep:base, "1,", "0")
                )
            )
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:sob + 0.49sw, :sob + 1.36km]);
        line_label(:right:n, sm[:sob + 1.35km] >> 0.5mt, (0.8dt, 0dt), "SMM");
        track(sm[:sob + 1.34km, :sun - 0.49sw]);
    }

    with link = "point.dk.Sundsmark", railway = :station {
        track(sm[:sun - 0.5sw, :sun + 0.5sw]);
        marker(:left :de.hp, sm[:sun] << 0.5mt);
        station(:top, sm[:sun] << 0.5mt << 1sh + (-1.3dt, -1dt),
            "Sundsmark",
            hbox(:center:top,
                vbox(:right:top, span(:former, "SSB: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "2,", "3"),
                    hbox(:sep:base, "3,", "2")
                )
            )
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:sun + 0.49sw, :spa - 0.49sw]);
    }

    with link = "point.dk.Spang", railway = :station {
        track(sm[:spa - 0.5sw, :spa + 0.5sw]);
        marker(:left :de.hp, sm[:spa] << 0.5mt);
        station(:top, sm[:spa] << 0.5mt << 1sh + (-1dt, -1dt),
            vbox(:center:base,
                span(:former, "Spang-Ulkebüll"),
                span(:former, "Spang-Ulkebøl")
            ),
            "Spang",
            hbox(:center:top,
                vbox(:right:top, span(:former, "SSB: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "3,", "2"),
                    hbox(:sep:base, "4,", "0")
                )
            )
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:spa + 0.49sw, :vol.yv]);
        track(sm[:vol.yv, :vol - 0.49sw]);
    }

    with link = "point.dk.Vollerup", railway = :station {
        track(sm[:vol - 0.5sw, :vol + 0.5sw]);
        marker(:left :de.bf, sm[:vol] << 0.5mt);
        station(:bottom, sm[:vol] >> 0.5mt + (-2dt, 1.2dt),
            "Vollerup", "SMM: 5,5"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:vol + 0.49sw, :vol + 0.96km]);
        line_label(:right:n, sm[:vol + 0.95km] >> 0.5mt, "SMM");
        track(sm[:vol + 0.94km, :vol.yo - 0.4km]);
        track(:station, sm[:vol.yo - 0.41km, :vol.yo + 0.1dl]);
        track(sm[:vol.yo, :kir - 0.49sw]);
    }

    with link = "point.dk.Kirke-Hørup", railway = :station {
        track(sm[:kir - 0.5sw, :kir + 0.5sw]);
        marker(:left :de.hp, sm[:kir] << 0.5mt);
        marker(:left :de.exbf, sm[:kir] << 0.5mt);
        station(:top, sm[:kir] << 0.5mt << 1.4sh << 0.7dt,
            vbox(:center:base,
                span(:former, "Hörup"),
                span(:former, "Hørup")
            ),
            "Kirke-Hørup", 
            hbox(:center:top,
                vbox(:right:top, span(:former, "SSB: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "7,", "4"),
                    hbox(:sep:base, "8,", "6")
                )
            )
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:kir + 0.49sw, :maj - 0.49sw]);
    }

    with link = "point.dk.Majbøl", railway = :station {
        track(sm[:maj - 0.5sw, :maj + 0.5sw]);
        marker(:left :de.hp, sm[:maj] << 0.5mt);
        station(:top, sm[:maj] << 0.5mt << 1sh << 0.8dt,
            span(:former, "Maibüll"),
