                vbox(:right:top, span(:former, "SSB: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "9,", "1"),
                    hbox(:sep:base, "10,", "3")
                )
            )
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:maj + 0.49sw, :maj.yo]);
        track(:station, sm[:maj.yo, :maj.yo + 0.4km + 1sw]);
        track(sm[:maj.yo + 0.4km + 0.99sw, :ota - 0.49sw]);
    }

    with link = "point.dk.Over-Tandslet", railway = :station {
        track(sm[:ota - 0.5sw, :ota + 0.5sw]);
        marker(:left :de.bf, sm[:ota] << 0.5mt);
        station(:bottom, sm[:ota] >> 0.5mt + (-3.5dt, 1.8dt),
            "Over-Tandslet", "SMM: 13,0"
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:ota + 0.49sw, :nta.yt - 0.99seg]);
        track(:station, sm[:nta.yt - 1seg, :nta.yt + 0.1dl]);
    }

    with link = "point.dk.Neder-Tandslet", railway = :station {
        track(sm[:nta.yt, :nta + 0.5sw]);
        marker(:left :de.bf, sm[:nta] << 0.5mt);
        station(:top, sm[:nta] << 0.5mt << 1sh + (1.5dt, -1.2dt),
            span(:former, "Niedertandslet"),
            "Neder-Tandslet",
            hbox(:center:top,
                vbox(:right:top, span(:former, "SSB: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "13,", "2"),
                    hbox(:sep:base, "14,", "4")
                )
            )
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:nta + 0.49sw, :lmo - 0.49sw]);
    }

    with link = "point.dk.Lille-Mommark", railway = :station {
        track(sm[:lmo - 0.5sw, :lmo.ys + 0.5seg]);
        marker(:right :de.hp, sm[:lmo] >> 0.5mt);
        marker(:right :de.exbf, sm[:lmo] >> 0.5mt);
        station(:bottom, sm[:lmo] >> 0.5mt >> 1.4sh + (-3dt, 0.8dt),
            span(:former, "Klein Mummark"),
            span(:bold, "Lille-Mommark"),
            hbox(:center:top,
                vbox(:right:top,
                    span(:former, "SSB: "),
                    span(:former, "LMM: "),
                    "SMM: "
                ),
                vbox(:sep:top,
                    hbox(:sep:base :former, "14,", "6"),
                    hbox(:sep:base :former, "14,", "6"),
                    hbox(:sep:base, "15,", "7")
                )
            )

        );
    }

    with link = "line.dk.SMM" {
        track(sm[:lmo.ys + 0.49seg, :lmo.ys + 1.11km]);
        line_label(:left:s, sm[:lmo.ys + 1.1km] << 0.5mt, span(:former, "LMM"));
        line_label(:right:n, sm[:lmo.ys + 1.1km] >> 0.5mt, "SMM");
        track(sm[:lmo.ys + 1.09km, :sar - 0.49sw]);
    }

    with link = "point.dk.Sarup", railway = :station {
        track(sm[:sar - 0.5sw, :sar + 0.5sw]);
        marker(:right :de.hp, sm[:sar] >> 0.5mt);
        station(:bottom, sm[:sar] >> 0.5mt >> 1sh + (2dt, 0.8dt),
            "Sarup",
            hbox(:center:top,
                vbox(:right:top, span(:former, "LMM: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "16,", "2"),
                    hbox(:sep:base, "17,", "5")
                )
            )
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:sar + 0.49sw, :mof - 0.49sw]);
    }

    with link = "point.dk.Mommark-Færgegård", railway = :station {
        track(sm[:mof - 0.5sw, :mof + 0.5sw]);
        marker(:right :de.hp, sm[:mof] >> 0.5mt);
        station(:right, sm[:mof] >> 0.5mt >> 1sh + (1dt, 1.1dt),
            vbox(:left:base,
                span(:former, " Mummark Fähre"),
                span(:former, " Mommark Færge")
            ),
            "Mommark Færgegård",
            hbox(:center:top,
                vbox(:right:top, span(:former, "LMM: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "18,", "0"),
                    hbox(:sep:base, "19,", "3")
                )
            )
        );
    }

    with link = "line.dk.SMM" {
        track(sm[:mof + 0.49sw, :mom - 0.49sw]);
    }

    with link = "point.dk.Mommark-Færge", railway = :station {
        track(sm[:mom - 0.5sw, :mom.f]);
        marker(:right :de.bf, sm[:mom] >> 0.5mt);
        station(:right, sm[:mom] >> 0.5mt >> 1sh + (1.2dt, 1.1dt),
            span(:bold, "Mommark Færge"),
            hbox(:center:top,
                vbox(:right:top, span(:former, "LMM: "), "SMM: "),
                vbox(:sep:top,
                    hbox(:sep:base :former, "18,", "7"),
                    hbox(:sep:base, "19,", "9")
                )
